function toHalfWidth(t){return t.replace(/[０-９]/g,t=>String.fromCharCode(t.charCodeAt(0)-65248)).replace(/，/g,",")}function sanitize(t){let e=toHalfWidth(t.value);e=e.replace(/[^\d,]/g,""),t.value=e}const input=document.getElementById("id_amount");if(input){let t=!1;input.addEventListener("compositionstart",()=>{t=!0}),input.addEventListener("compositionend",e=>{t=!1,sanitize(e.target)}),input.addEventListener("input",e=>{t||sanitize(e.target)}),input.addEventListener("blur",t=>{let e=toHalfWidth(t.target.value);if(""===e)return;const n=e.replace(/,/g,"");t.target.value=Number(n).toLocaleString("ja-JP")})}